--- pc2.startup
tee /etc/bind/named.conf >/dev/null <<'EOF'
options {
    directory "/var/cache/bind";
    listen-on { any; };
    listen-on-v6 { none; };
    recursion no;
    allow-query { any; };
};
zone "." { type master; file "/etc/bind/zones/db.root"; };
EOF
--- pc3.startup
